    public void initialize(){
    	Hibernate.initialize(assignmentParts);
    }

    @PrePersist
    void prePersist() {
    	ctlCreTs = new Date();
    	ctlCreUid = ThreadLocalUserInfo.getUserId();
    	updateAssignmentTimeRange();

    	ctlModTs = ctlCreTs;
    	ctlModUid = ctlCreUid;
    }

    @PreUpdate
    void preUpdate() {
    	ctlModTs = new Date();
    	ctlModUid = ThreadLocalUserInfo.getUserId();
    	updateAssignmentTimeRange();	
		
    }

    /**
     * Update the time range the assignment spans through: the soonest date when the assignment
     * has any event (preload or load part planned start or real start whichever is sooner) 
     * and the latest date after what the assignment has no event
     * at all (finish part planned start or real start whichever is later).
     */
	private void updateAssignmentTimeRange() {
		if (assignmentParts == null ) {
			return;
		}
		if (assignmentParts.isEmpty()){
			this.minStart = null;
			this.maxEnd = null;
			return;
		}
		if (this.minStart != null || this.maxEnd != null) {
			return;
		}
			
		List<AssignmentPartEntity> assignmentParts = new ArrayList<AssignmentPartEntity>(getAssignmentParts());
		Collections.sort(assignmentParts, new Comparator<AssignmentPartEntity>() {
		    public int compare(AssignmentPartEntity obj1, AssignmentPartEntity obj2) {
				return obj1.getAssignmentPartSeqNo().compareTo(obj2.getAssignmentPartSeqNo());
		    }
		});
		
		AssignmentPartEntity soonestPart = assignmentParts.get(0);
		AssignmentPartEntity finishPart = assignmentParts.get(assignmentParts.size()-1);
		this.minStart = soonestPart.getPlannedStart();
		if (soonestPart.getPlannedStart() != null && soonestPart.getRealStart() != null && soonestPart.getPlannedStart().compareTo(soonestPart.getRealStart()) > 0) {
			this.minStart = soonestPart.getRealStart();	
		}
		this.maxEnd = finishPart.getPlannedStart();
		if (finishPart.getPlannedStart() != null && finishPart.getRealStart() != null && finishPart.getRealStart().compareTo(finishPart.getPlannedStart()) > 0) {
			this.maxEnd = finishPart.getRealStart();	
		}
	}
    
